-- 341 exercícios.
-- 2766 associações entre exercícios e subgrupos musculares.
--
-- Pré-requisitos:
--   1. seed de activity_types;
--   2. seed de equipment_types;
--   3. seed de muscle_groups;
--   4. seed de muscle_subgroups;
--   5. seed de exercises com os mesmos nomes, equipamentos e atividades.
--
-- Como exercises ainda não possui um código natural, cada exercício é
-- localizado pela combinação exata: name + equipment_type.code + activity_type.code.
-- A migration valida que cada combinação resolve exatamente um exercício,
-- que todos os 341 exercícios têm ao menos um PRIMARY e que nenhum vínculo
-- exercício/subgrupo está duplicado.

CREATE TEMP TABLE exercise_muscle_target_seed (
    exercise_name VARCHAR(150) NOT NULL,
    equipment_code VARCHAR(50) NOT NULL,
    activity_code VARCHAR(50) NOT NULL,
    muscle_subgroup_code VARCHAR(80) NOT NULL,
    target_role VARCHAR(30) NOT NULL
) ON COMMIT DROP;

INSERT INTO exercise_muscle_target_seed (
    exercise_name,
    equipment_code,
    activity_code,
    muscle_subgroup_code,
    target_role
)
