-- Validações estruturais do seed.
DO $$
DECLARE
distinct_exercise_count INTEGER;
BEGIN
    IF EXISTS (
        SELECT 1
        FROM exercise_muscle_target_seed
        WHERE target_role NOT IN ('PRIMARY', 'SECONDARY', 'STABILIZER')
    ) THEN
        RAISE EXCEPTION 'Seed contém target_role inválido.';
END IF;

    IF EXISTS (
        SELECT 1
        FROM exercise_muscle_target_seed
        GROUP BY exercise_name, equipment_code, activity_code, muscle_subgroup_code
        HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'Seed contém associação duplicada entre exercício e subgrupo.';
END IF;

SELECT COUNT(*)
INTO distinct_exercise_count
FROM (
         SELECT DISTINCT exercise_name, equipment_code, activity_code
         FROM exercise_muscle_target_seed
     ) seeded_exercises;

IF distinct_exercise_count <> 341 THEN
        RAISE EXCEPTION
            'Quantidade de exercícios mapeados inválida. Esperado: 341. Encontrado: %.',
            distinct_exercise_count;
END IF;

    IF EXISTS (
        SELECT 1
        FROM exercise_muscle_target_seed
        GROUP BY exercise_name, equipment_code, activity_code
        HAVING COUNT(*) FILTER (WHERE target_role = 'PRIMARY') = 0
    ) THEN
        RAISE EXCEPTION 'Existe exercício sem alvo PRIMARY.';
END IF;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT DISTINCT equipment_code
            FROM exercise_muscle_target_seed
        ) seed
        WHERE (
            SELECT COUNT(*)
            FROM equipment_types
            WHERE code = seed.equipment_code
        ) <> 1
    ) THEN
        RAISE EXCEPTION 'Um ou mais equipment_types não foram resolvidos exatamente uma vez.';
END IF;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT DISTINCT activity_code
            FROM exercise_muscle_target_seed
        ) seed
        WHERE (
            SELECT COUNT(*)
            FROM activity_types
            WHERE code = seed.activity_code
        ) <> 1
    ) THEN
        RAISE EXCEPTION 'Um ou mais activity_types não foram resolvidos exatamente uma vez.';
END IF;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT DISTINCT muscle_subgroup_code
            FROM exercise_muscle_target_seed
        ) seed
        WHERE (
            SELECT COUNT(*)
            FROM muscle_subgroups
            WHERE code = seed.muscle_subgroup_code
        ) <> 1
    ) THEN
        RAISE EXCEPTION 'Um ou mais muscle_subgroups não foram resolvidos exatamente uma vez.';
END IF;

    IF EXISTS (
        SELECT 1
        FROM (
            SELECT DISTINCT exercise_name, equipment_code, activity_code
            FROM exercise_muscle_target_seed
        ) seed
        WHERE (
            SELECT COUNT(*)
            FROM exercises exercise
            INNER JOIN equipment_types equipment
                ON equipment.id = exercise.equipment_type_id
            INNER JOIN activity_types activity
                ON activity.id = exercise.activity_type_id
            WHERE exercise.name = seed.exercise_name
              AND equipment.code = seed.equipment_code
              AND activity.code = seed.activity_code
        ) <> 1
    ) THEN
        RAISE EXCEPTION
            'Um ou mais exercícios não foram resolvidos exatamente uma vez por nome, equipamento e atividade.';
END IF;
END;
$$;

INSERT INTO exercise_muscle_targets (
    exercise_id,
    muscle_subgroup_id,
    target_role,
    active,
    created_at
)
SELECT
    exercise.id,
    muscle_subgroup.id,
    seed.target_role,
    TRUE,
    CURRENT_TIMESTAMP
FROM exercise_muscle_target_seed seed
         INNER JOIN equipment_types equipment
                    ON equipment.code = seed.equipment_code
         INNER JOIN activity_types activity
                    ON activity.code = seed.activity_code
         INNER JOIN exercises exercise
                    ON exercise.name = seed.exercise_name
                        AND exercise.equipment_type_id = equipment.id
                        AND exercise.activity_type_id = activity.id
         INNER JOIN muscle_subgroups muscle_subgroup
                    ON muscle_subgroup.code = seed.muscle_subgroup_code;

-- Confirma que cada linha do seed foi persistida com o mesmo target_role.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM exercise_muscle_target_seed seed
        INNER JOIN equipment_types equipment
            ON equipment.code = seed.equipment_code
        INNER JOIN activity_types activity
            ON activity.code = seed.activity_code
        INNER JOIN exercises exercise
            ON exercise.name = seed.exercise_name
           AND exercise.equipment_type_id = equipment.id
           AND exercise.activity_type_id = activity.id
        INNER JOIN muscle_subgroups muscle_subgroup
            ON muscle_subgroup.code = seed.muscle_subgroup_code
        LEFT JOIN exercise_muscle_targets target
            ON target.exercise_id = exercise.id
           AND target.muscle_subgroup_id = muscle_subgroup.id
           AND target.target_role = seed.target_role
        WHERE target.id IS NULL
    ) THEN
        RAISE EXCEPTION 'Nem todas as associações do seed foram persistidas corretamente.';
END IF;
END;
$$;
